import valueParser from 'postcss-value-parser';

import { isValueFunction, isValueString, isValueWord } from '../../utils/typeGuards.mjs';
import { assertNumber } from '../../utils/validateTypes.mjs';
import isNonNegativeInteger from '../../utils/isNonNegativeInteger.mjs';
import isStandardSyntaxValue from '../../utils/isStandardSyntaxValue.mjs';
import matchesStringOrRegExp from '../../utils/matchesStringOrRegExp.mjs';
import { mayIncludeRegexes } from '../../utils/regexes.mjs';
import report from '../../utils/report.mjs';
import ruleMessages from '../../utils/ruleMessages.mjs';
import validateObjectWithProps from '../../utils/validateObjectWithProps.mjs';
import validateOptions from '../../utils/validateOptions.mjs';

const ruleName = 'declaration-property-max-values';

const messages = ruleMessages(ruleName, {
	expected: (property, max) => `Too many values for property "${property}", maximum ${max}`,
});

const meta = {
	url: 'https://stylelint.io/user-guide/rules/declaration-property-max-values',
};

/**
 * @param {valueParser.Node} node
 */
const isValueNode = (node) => {
	return isValueWord(node) || isValueFunction(node) || isValueString(node);
};

/** @type {import('stylelint').CoreRules[typeof ruleName]} */
const rule = (primary) => {
	return (root, result) => {
		const validOptions = validateOptions(result, ruleName, {
			actual: primary,
			possible: [validateObjectWithProps(isNonNegativeInteger)],
		});

		if (!validOptions) {
			return;
		}

		root.walkDecls((decl) => {
			const { prop, value } = decl;

			if (!mayIncludeRegexes.multipleValues.test(value)) return;

			if (!isStandardSyntaxValue(value)) return;

			const propLength = valueParser(value).nodes.filter(isValueNode).length;

			const propKey = Object.keys(primary).find((propIdentifier) =>
				matchesStringOrRegExp(prop, propIdentifier),
			);

			if (!propKey) {
				return;
			}

			const max = primary[propKey];

			assertNumber(max);

			if (propLength <= max) {
				return;
			}

			report({
				message: messages.expected,
				messageArgs: [prop, max],
				node: decl,
				result,
				ruleName,
			});
		});
	};
};

rule.ruleName = ruleName;
rule.messages = messages;
rule.meta = meta;
export default rule;
